"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["2817"],{64551(e){e.exports=JSON.parse('{"id":"F095","slug":"comparative-advantage","name":"Comparative Advantage and Gains from Trade","subject":"Economics for Finance","section":"Markets and the Economy","topic":"Global trade and supply chains","level":"Beginner","aliases":["global trade and supply chains","opportunity cost","terms of trade","specialization"],"formula":{"latex":"OC_{W}^{A}=\\\\frac{a_{W}^{A}}{a_{C}^{A}},\\\\quad OC_{W}^{B}=\\\\frac{a_{W}^{B}}{a_{C}^{B}},\\\\quad OC_{W}^{B}<TOT<OC_{W}^{A}","also":[],"text":"Opportunity cost of one unit of wine, in cloth = hours per wine / hours per cloth. The country with the lower opportunity cost has the comparative advantage. Both gain if they trade at a price (terms of trade) between the two opportunity costs"},"symbols":[{"symbol":"a","meaning":"Labor hours needed to make one unit of a good in a country","unit":"hours"},{"symbol":"OC","meaning":"Opportunity cost: units of the other good given up","unit":"number"},{"symbol":"TOT","meaning":"Terms of trade: units of cloth exchanged for one unit of wine","unit":"number"}],"when_to_use":"Use it to see why trade benefits both sides even when one country is better at everything. What counts is the relative cost, not the absolute cost. Each country should specialize where its opportunity cost is lower and trade for the rest. Real trade also faces transport costs, tariffs, and supply-chain risk, which can outweigh small gains.","worked_example":{"problem":"Country A needs 2 hours per cloth and 4 hours per wine. Country B needs 3 hours per cloth and 3 hours per wine.","inputs":{"ac":2,"aw":4,"bc":3,"bw":3},"steps":[{"label":"A: cloth given up per wine = aw / ac","working":"4 / 2","value":"2.000"},{"label":"B: cloth given up per wine = bw / bc","working":"3 / 3","value":"1.000"},{"label":"A: wine given up per cloth","working":"2 / 4","value":"0.500"},{"label":"B: wine given up per cloth","working":"3 / 3","value":"1.000"},{"label":"Lower limit of the terms of trade (cloth per wine)","working":"min(2, 1)","value":"1.000"},{"label":"Upper limit of the terms of trade","working":"max(2, 1)","value":"2.000"},{"label":"A midpoint price","working":"(1+2) / 2","value":"1.500"},{"label":"Cloth saved per wine by the higher-cost producer, at the midpoint","working":"2-1.5","value":"0.500"}],"answer":"In wine terms, A gives up 2.000 cloth per wine and B gives up 1.000. Wine is cheaper for B. For cloth, A gives up 0.500 wine per cloth and B gives up 1.000. Any price between 1.000 and 2.000 cloth per wine benefits both: at 1.500, A saves 0.500 cloth per wine it imports."},"calculator":{"available":true,"inputs":[{"id":"ac","label":"Country A hours per cloth","unit":"hours","type":"number","default":2,"hint":""},{"id":"aw","label":"Country A hours per wine","unit":"hours","type":"number","default":4,"hint":""},{"id":"bc","label":"Country B hours per cloth","unit":"hours","type":"number","default":3,"hint":""},{"id":"bw","label":"Country B hours per wine","unit":"hours","type":"number","default":3,"hint":""}],"checks":[{"expr":"ac>0 and aw>0 and bc>0 and bw>0 and aw/ac!=bw/bc","message":"Enter hours above zero, and the two opportunity costs must differ or there are no gains."}],"steps":[{"id":"ocA","label":"A: cloth given up per wine = aw / ac","expr":"aw/ac","format":"num3"},{"id":"ocB","label":"B: cloth given up per wine = bw / bc","expr":"bw/bc","format":"num3"},{"id":"ocAc","label":"A: wine given up per cloth","expr":"ac/aw","format":"num3"},{"id":"ocBc","label":"B: wine given up per cloth","expr":"bc/bw","format":"num3"},{"id":"lo","label":"Lower limit of the terms of trade (cloth per wine)","expr":"min(ocA, ocB)","format":"num3"},{"id":"hi","label":"Upper limit of the terms of trade","expr":"max(ocA, ocB)","format":"num3"},{"id":"mid","label":"A midpoint price","expr":"(lo+hi)/2","format":"num3"},{"id":"gainA","label":"Cloth saved per wine by the higher-cost producer, at the midpoint","expr":"hi-mid","format":"num3"}],"results":["ocA","ocB","lo","hi"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"ocA":2,"ocB":1,"ocAc":0.5,"ocBc":1,"lo":1,"hi":2,"mid":1.5,"gainA":0.5}},"finder":{"finds":"Who should produce what, and the price range at which both gain","needs":"Hours per unit for each good in each country"},"related":[{"slug":"balance-of-payments-identity","name":"Balance of Payments Identity"},{"slug":"gdp-nominal-real","name":"GDP: Expenditure Approach, Real GDP and Deflator"},{"slug":"ppp-expected-rate","name":"Purchasing Power Parity: Valuation and Expected Rate"}],"related_ids":["F447","F080","F436"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>A</mi></msubsup><mo>=</mo><mfrac><msubsup><mi>a</mi><mi>W</mi><mi>A</mi></msubsup><msubsup><mi>a</mi><mi>C</mi><mi>A</mi></msubsup></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>B</mi></msubsup><mo>=</mo><mfrac><msubsup><mi>a</mi><mi>W</mi><mi>B</mi></msubsup><msubsup><mi>a</mi><mi>C</mi><mi>B</mi></msubsup></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>B</mi></msubsup><mo>&lt;</mo><mi>T</mi><mi>O</mi><mi>T</mi><mo>&lt;</mo><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>A</mi></msubsup></mrow><annotation encoding=\\"application/x-tex\\">OC_{W}^{A}=\\\\frac{a_{W}^{A}}{a_{C}^{A}},\\\\quad OC_{W}^{B}=\\\\frac{a_{W}^{B}}{a_{C}^{B}},\\\\quad OC_{W}^{B}&lt;TOT&lt;OC_{W}^{A}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>A</mi></msubsup></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle OC_{W}^{A}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mfrac><msubsup><mi>a</mi><mi>W</mi><mi>A</mi></msubsup><msubsup><mi>a</mi><mi>C</mi><mi>A</mi></msubsup></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\frac{a_{W}^{A}}{a_{C}^{A}}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>B</mi></msubsup></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle OC_{W}^{B}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mfrac><msubsup><mi>a</mi><mi>W</mi><mi>B</mi></msubsup><msubsup><mi>a</mi><mi>C</mi><mi>B</mi></msubsup></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\frac{a_{W}^{B}}{a_{C}^{B}}</annotation></semantics></math></span>"},{"lhs":null,"rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>B</mi></msubsup><mo>&lt;</mo><mi>T</mi><mi>O</mi><mi>T</mi><mo>&lt;</mo><mi>O</mi><msubsup><mi>C</mi><mi>W</mi><mi>A</mi></msubsup></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle OC_{W}^{B}&lt;TOT&lt;OC_{W}^{A}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"common-size-statement","name":"Common-Size Statements"},"next":{"slug":"cagr","name":"Compound Annual Growth Rate (CAGR)"},"lesson":null,"total":522}')}}]);